import streamlit as st

from dashboard.api_client import ApiClientError, case_label, list_cases, request_api

st.set_page_config(page_title="Analysis | CrimeVision AI", layout="wide")
st.title("Evidence analysis")
st.info(
    "Detections and transcripts are observations generated by AI. Hypotheses are inferences. "
    "Review all outputs; do not treat them as verified facts."
)

try:
    cases = list_cases()
except ApiClientError as exc:
    st.error(str(exc))
    st.stop()

if not cases:
    st.info("Create a case and upload evidence first.")
    st.stop()

selected_case = st.selectbox("Case", cases, format_func=case_label)
try:
    evidence_items = request_api(
        "GET", f"/cases/{selected_case['case_id']}/evidence"
    ).json()
except ApiClientError as exc:
    st.error(str(exc))
    st.stop()

if not evidence_items:
    st.info("This case has no evidence to analyze.")
    st.stop()

selected_evidence = st.selectbox(
    "Evidence",
    evidence_items,
    format_func=lambda item: f"{item['original_filename']} ({item['media_type']}) — {item['evidence_id']}",
)

endpoint_by_type = {
    "image": "analyze-image",
    "audio": "transcribe-audio",
    "video": "analyze-video",
}
action = endpoint_by_type[selected_evidence["media_type"]]

if st.button(f"Run {selected_evidence['media_type']} analysis"):
    try:
        result = request_api(
            "POST",
            f"/evidence/{selected_evidence['evidence_id']}/{action}",
        ).json()
        st.session_state["latest_analysis"] = result
    except ApiClientError as exc:
        st.error(str(exc))

if "latest_analysis" in st.session_state:
    st.subheader("Latest analysis response")
    st.json(st.session_state["latest_analysis"])

st.subheader("Saved findings")
try:
    findings = request_api(
        "GET",
        f"/cases/{selected_case['case_id']}/findings",
        params={"evidence_id": selected_evidence["evidence_id"]},
    ).json()
    st.caption(f"{findings['count']} saved finding(s)")
    for finding in findings["findings"]:
        title = (
            f"{finding['finding_type']} | {finding['label']} "
            f"| {finding['status']} | {finding['finding_id']}"
        )
        with st.expander(title):
            st.write(finding["description"])
            st.json(
                {
                    "evidence_id": finding["evidence_id"],
                    "source_time_sec": finding["source_time_sec"],
                    "source_end_time_sec": finding.get("source_end_time_sec"),
                    "frame_index": finding["frame_index"],
                    "confidence": finding["confidence"],
                    "model_name": finding["model_name"],
                    "model_version": finding["model_version"],
                }
            )
except ApiClientError as exc:
    st.error(str(exc))
